import pyomo.environ as pyo

DATA = {
    "cars": list(range(1, 16)),
    "sides": [0, 1],
    "length": {
        1: 4.0, 2: 4.5, 3: 5.0, 4: 4.1, 5: 2.4,
        6: 5.2, 7: 3.7, 8: 3.5, 9: 3.2, 10: 4.5,
        11: 2.3, 12: 3.3, 13: 3.8, 14: 4.6, 15: 3.0,
    },
    "side_capacity": 15.0,
    "use_capacity": False,   # set True for part (b): each side <= 15 m exactly
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.CARS = pyo.Set(initialize=d["cars"])
    model.SIDES = pyo.Set(initialize=d["sides"])

    # park[i,s] = 1 if car i is parked on side s
    model.park = pyo.Var(model.CARS, model.SIDES, within=pyo.Binary)

    # total length occupied on each side
    model.occupy = pyo.Var(model.SIDES, within=pyo.NonNegativeReals)

    # objective: minimise total occupied length across both sides
    def obj_rule(m):
        return sum(m.occupy[s] for s in m.SIDES)
    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # each car parked on exactly one side
    def one_side_rule(m, i):
        return sum(m.park[i, s] for s in m.SIDES) == 1
    model.one_side = pyo.Constraint(model.CARS, rule=one_side_rule)

    # occupation definition per side
    def occupy_rule(m, s):
        return m.occupy[s] == sum(d["length"][i] * m.park[i, s] for i in m.CARS)
    model.occupy_def = pyo.Constraint(model.SIDES, rule=occupy_rule)

    # optional: each side cannot exceed 15 m exactly
    if d["use_capacity"]:
        def cap_rule(m, s):
            return m.occupy[s] <= d["side_capacity"]
        model.side_cap = pyo.Constraint(model.SIDES, rule=cap_rule)

    return model


